(* [comment removed for export] *)
Lemma brk_grow_facts_ok : forall E cs R FULL model M bb bk d (dwg : word),
  cs_ok E cs R FULL model ->
  split_lit (a_brk cs) = (bb, bk) ->
  0 < d -> bv_unsigned (vm_brk (m_vmmaps model)) + d + 4096 <= MID_LO + 2 ^ 32 ->
  bv_unsigned dwg = d + 4096 ->
  region_free (vm_reserved (m_vmmaps model) ++ vm_maps (m_vmmaps model)) (vm_brk (m_vmmaps model)) dwg = true ->
  know_ok SEGS E M (brk_grow_facts (kn cs) (a_maps cs) bb bk d).
